/*
	Instable #WCCChallenge Scroll OR Rhythm 27.3.24 
	#generativeart #creativecoding #p5js

  Dear Raph and creative coding community,

	inspired by a submission of the swiss design WCCChallenge and 
	the original "Première exposition du Collectif Instable"
 	https://inspirationfeed.com/swiss-graphic-design
 	https://inspirationfeed.com/wp-content/uploads/2017/03/43.jpg

	Circular objects rotating in different speeds playing note on every n-th evolution 
	Circles flashes, when a tone is played.
	Sounds are generated with ToneJS
	After looking on it for a while, you can name it also PsychoDeck ^^

	Interactions:
	- Scroll  and speed can be adjusted by mouse scroll wheel when
	  hovering over the objects.
	- Key [d] for debugMode
	- LMB over circle to mute/unmute
	- Double Click for new rhythm

	Help:
	- console.log output from ToneJS (%c * Tone.js v14.8.49 * background: #000; color: #fff)
    shall be not visible

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

let debugMode = false;
let objs;

const niceSeeds = [4945945, 8331424, 4903367, 8877239, 2163893, 5795523, 3845325];
let seedSelect;

// ToDo: load samples from https://github.com/crabacus/the-open-source-drumkit

function setup(seed) {
  createCanvas(S = min(innerWidth, innerHeight), S);
	describe("audio generator: each cell represents a tone played at a specific speed and beat")
	colorMode(HSB)
	frameRate(60);
	// noLoop() removed for animation
	if (frameCount > 0) loop();
	describe("")

	const rSeed = seed || ~~random(9999999+hour()+minute()+second());
	randomSeed(rSeed); // force given seed, and randomize after
	console.log("randomSeed("+rSeed+")");

	const N = 3;
	const O = S / N;
	const M = O / 2;

	objs = [];
	const notes = ["C2", "C3", "G3", "C4", "E4", "G4", "Bb4", "C5", "D5", "E5", "F#5", "G5", "A5"];
	const notes_ = ["C4", "D4", "E4", "F4", "G4", "A4", "H4", "C5", "D5"]; // not working

	// https://tonejs.github.io/docs/r13/MembraneSynth
	const synthOpt =  {
			pitchDecay : 0.05 ,
			octaves : 10 ,
			oscillator : {
				type : "sine"
			},
			envelope : {
				attack : 0.001 ,
				decay : 0.4 ,
				sustain : 0.01 ,
				release : 0.8 ,
				attackCurve : "exponential"
			}
	};

	for (let yy = 0; yy < N; yy++) {
		for (let xx = 0; xx < N; xx++) {
			const i = xx + yy * N;
			const x = M + xx * O;
			const y = M + yy * O;
			const r = M;
			objs.push(
				{x, y, r, 
				 typ: i + 2,
				 params: { p: i + 1, a: 0, da: 0.01 * (1+xx+yy), n: notes[i], t: 1/pow(2, ~~random(4)), s: new Tone.MembraneSynth(synthOpt).toDestination(), mute: false }, 
				 clr: {h: random(360), s: 55, b: 75}
				}
			);
		}
	}
	if (debugMode) console.log(objs)

	// create seed slider right from canvas
	seedSelect = createSelect();
  seedSelect.position(S, 0);
	seedSelect.option('');
  for (let i of niceSeeds) seedSelect.option(""+i);

	// next seed randomized again
	randomSeed(~~random(9999999+hour()+minute()+second()))
}

function keyPressed() {
  if (key === "d" || key === "D") {
		debugMode = !debugMode;
  }
}

function draw() {
  background("black");

	if (frameCount < 2) {
		push();
		stroke("grey");
		noFill();
		const d = width/3;
		strokeWeight(d/20);
		for (let i = 0; i < 5; i++) circle(random(width), random(width), d);
		noStroke();
		fill("white");
		textAlign(CENTER, CENTER);
		textSize(width/10);
		textFont("Helvetica");
		text("Audio On\nPress LMB to start", width/2, height/2);
		pop();
		return;
	}

	for (let o of objs) {
		pCircle(o.x, o.y, o.r, o.params, o.clr);
	}
}

function doubleClicked() {
	if (mouseButton === LEFT) {
		setup(seedSelect.selected());
	}
}

function mouseClicked() {
	if (mouseButton === LEFT) {
		// console.log("fc" + frameCount)
		if (frameCount <= 1) {
			loop();
			return;
		}
		for (let o of objs) {
			if (dist(o.x, o.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) < o.r) {
				// print(event.delta);
				o.params.mute = !o.params.mute;
			}
		}
	}
}

function mouseWheel(event) {
	for (let o of objs) {
		if (dist(o.x, o.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) < o.r) {
			// print(event.delta);
			o.params.da = constrain(o.params.da + Math.sign(event.delta) * 0.002, 0, 0.4);
		}
	}
}

function pCircle(x, y, r, params, clr) {
  let sw = params.sw || r / 20; // stroke weight
  let pa = params.p || -1; // pattern

	// check if evolution to play note
	// console.log("rotate (" + params.p + "): " + params.a)
	/* not working properly, but also for negative direction
	let playTone = params.da < 0 && (TWO_PI + params.a + params.da) % TWO_PI >= TWO_PI - params.da ||
				((TWO_PI + params.a + params.da) % TWO_PI) - TWO_PI > params.da;
	*/
	const ma = TWO_PI * params.t; // max angle
	const na = (ma + params.a + params.da) % ma;
	var playTone = na < params.a;
	if (playTone) {
		// console.log(`${params.a} ${params.da}`)
		if (!params.mute) {
			params.s.triggerAttackRelease(params.n, params.t, Tone.now()); // "8n"
			clr.s = 100;
			// console.log("playTone " + params.p + " " + ~~millis() + "ms")
		}
	}

	params.a = na; // (TWO_PI + params.a + params.da) % TWO_PI;
	let an = params.a;

	// display debug infos
	if (debugMode) {
		push()
		translate(x-r, y-r)
		noStroke()
		fill("silver")
		text("ang:" + nf(params.a, 0, 2)+ ", da: " +nf(params.da,0,3) + 
				 "\ntyp:" + pa+", fr:"+params.t + 
				 "\nnote:" + params.n, 
				 0, 10)
		pop()
	}

  // mask in shape
  push();
  clip(() => {
    circle(x, y, r + r);
    // rect(x - r, y - r, r + r, r + r)
  });

  noFill();
	clr.s = constrain(clr.s-2, 0, 100)
  stroke(color(clr.h, clr.s, clr.b));
	// if hovering
	if (dist(x, y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) < r) stroke("rgb(255,252,246)");
  strokeWeight(sw * 0.5);

  // patterns
  switch (pa) {
		case 1: 
      { // outer circles
				const dr = 1.41 * sw;
        for (let cr = r - sw / 2 + dr * (1-fract(an/PI)); cr > 0; cr -= dr) {
          circle(x, y, cr + cr);
        }
      }
      break;

    case 2:
      { // star
        const u = TWO_PI * 2 * r;
        const n = u / sw / 2 / 2;
        const a = TWO_PI / n;
        translate(x, y);
        rotate(an);
        strokeWeight(sw * 0.5);
        for (let i = 0; i < n; i++) {
          line(0, 0, r, 0);
          rotate(a);
        }
      }
      break;

    case 3:
      { // diagonal lines
        translate(x, y);
        rotate(an);
        translate(-r, -r);
        strokeWeight(sw * 0.5);
        for (let i = 0; i <= r + r; i += sw + sw) {
          const l = r + r - i;
          line(i, 0, l + i, l);
          if (i) line(0, i, l, l + i);
        }
      }
      break;

    case 4:
      { // horiz + vert lines
        translate(x, y);
        rotate(an);
        translate(-r, -r);
        strokeWeight(sw * 0.5);
        for (let i = 0; i <= r + r; i += 1.41 * sw) {
          beginShape();
          vertex(0, i);
          vertex(r + r - i, i);
          vertex(r + r - i, r + r);
          endShape();
        }
      }
      break;

    case 5:
      { // zick zack lines
        var d = r * 0.25;
        translate(x, y);
        rotate(an);
        translate(-r, -r);
        strokeWeight(sw * 0.5);
        for (let i = -d; i <= r + r; i += sw + sw) {
          beginShape();
					for (let j = 0; j < 9; j++) {
	          vertex(j * d, i + (j % 2) * d);
					}
          endShape();
        }
      }
      break;

    case 6:
      { // dotted 1
        translate(x, y);
        rotate(an);
        translate(sw - r, sw - r);
        strokeWeight(sw);
        var n = (r / sw) * 2;
        for (let i = 0; i <= n; i++) {
          for (let j = 0; j <= n; j++) {
            if ((i + j) % 2) point(i * sw, j * sw);
          }
        }
      }
      break;

    case 7:
      { // dotted 2
        translate(x, y);
        rotate(an);
        translate(sw - r, sw - r);
        strokeWeight(sw);
        var n = r / sw;
        for (let i = 0; i <= n; i++) {
          for (let j = 0; j <= n; j++) {
            point(i * sw * 2, j * sw * 2);
          }
        }
      }
      break;

    case 8:
      { // dotted 3
        translate(x, y);
        rotate(an);
        translate(sw - r, sw - r);
        strokeWeight(sw);
        var n = r / sw;
        for (let i = 0; i <= n; i++) {
          for (let j = 0; j <= n; j++) {
            point(i * sw * 2, j * sw * 2 + (i % 2 ? 0 : sw));
          }
        }
      }
      break;

    default:
      // circle(x, y, (2 * r - sw) * -cos(an % HALF_PI));
			circle(x, y, (2 * r - sw) * (1-fract(an/TWO_PI)));
  }

  pop();

	// show status
	if (true) {
		push()
		translate(x, y);
		if (params.mute) {
			rotate(QUARTER_PI);
			strokeWeight(sw+sw+sw);
			stroke(0, 0, 75, 0.75)
			line(0, -r*0.5, 0, r*0.5);
			line(-r*0.5, 0, r*0.5, 0);
			rotate(-QUARTER_PI);
		}
		if (debugMode) {
			rotate(an);
			noStroke()
			fill("white")
			circle(r, 0, sw+sw)
		}
		pop()
	}
}

